/**
 * Content Injection Engine
 * Anti-Duplicate Strategy: Contextual Variable Composition
 *
 * Each spoke page is generated by combining:
 * 1. City/Geography context
 * 2. Genre/Style context
 * 3. Service/Product context
 * 4. Audience demographic
 *
 * Result: Unique content narrative for each page without copy-paste
 */

class ContentInjectionEngine {
  constructor(siteStructure) {
    this.structure = siteStructure;
    this.cache = new Map();
  }

  /**
   * Generate unique content narrative for a spoke page
   *
   * @param {string} hubPath - e.g., "/beatmaker-producer/"
   * @param {string} cityCode - e.g., "Paris_FR"
   * @param {string} genreCode - e.g., "Afrotrap"
   * @returns {Object} Content context object
   */
  generatePageContext(hubPath, cityCode, genreCode) {
    const cacheKey = `${hubPath}:${cityCode}:${genreCode}`;
    if (this.cache.has(cacheKey)) {
      return this.cache.get(cacheKey);
    }

    const cityData = this.structure.site.contextualVariables.cities[cityCode];
    const genreData = this.structure.site.contextualVariables.genres[genreCode];

    if (!cityData || !genreData) {
      throw new Error(`Invalid city or genre code: ${cityCode}, ${genreCode}`);
    }

    const context = {
      page: {
        title: this.generatePageTitle(cityCode, genreCode),
        metaDescription: this.generateMetaDescription(cityCode, genreCode),
        h1: this.generateH1(cityCode, genreCode),
        slug: this.generateSlug(cityCode, genreCode)
      },
      content: {
        intro: this.generateIntroSection(cityData, genreData),
        culturalContext: this.generateCulturalContext(cityData, genreData),
        useCases: this.generateUseCases(cityData, genreData),
        cta: this.generateCTA(cityCode, genreCode),
        faq: this.generateFAQ(cityData, genreData),
        internalLinks: this.generateInternalLinks(hubPath, cityCode, genreCode)
      },
      schema: {
        localBusiness: this.generateLocalBusinessSchema(cityCode),
        musicGroup: this.generateMusicGroupSchema(cityCode, genreCode),
        breadcrumb: this.generateBreadcrumb(hubPath, cityCode, genreCode)
      },
      seo: {
        keywords: this.generateKeywords(cityData, genreData),
        focusKeyword: `${genreCode} producer ${cityCode}`,
        relatedTerms: this.generateRelatedTerms(cityData, genreData)
      }
    };

    this.cache.set(cacheKey, context);
    return context;
  }

  /**
   * Generate unique page title avoiding duplicates
   */
  generatePageTitle(cityCode, genreCode) {
    const cityName = cityCode.split('_')[0];
    const genre = genreCode;

    const patterns = [
      `${genre} Producer in ${cityName} | Custom Beats & Mixing`,
      `${genre} Beatmaker ${cityName} | Professional Music Production`,
      `${cityName} ${genre} Producer | DJBILBOX - Beats & Label Services`,
      `${genre} Music Production ${cityName} | Beatmaking & Audio Post`
    ];

    // Deterministic rotation based on hash to avoid same pattern
    const hash = this.hashCode(`${cityCode}${genreCode}`);
    return patterns[Math.abs(hash) % patterns.length];
  }

  /**
   * Generate unique meta description
   */
  generateMetaDescription(cityCode, genreCode) {
    const cityName = cityCode.split('_')[0];
    const genre = genreCode;

    const patterns = [
      `Professional ${genre} production & mastering in ${cityName}. Custom beats, mixing services, and music label support for independent artists.`,
      `${cityName}-based ${genre} beatmaker with 15+ years in production. Beat creation, VST development, and full music label services.`,
      `${genre} producer serving artists worldwide from ${cityName}. Specialized in beatmaking, mixing, and independent label distribution.`,
      `Looking for quality ${genre} beats in ${cityName}? DJBILBOX offers production, mastering, and label services for your music.`
    ];

    const hash = this.hashCode(`meta_${cityCode}${genreCode}`);
    return patterns[Math.abs(hash) % patterns.length];
  }

  /**
   * Generate H1 - main semantic heading
   */
  generateH1(cityCode, genreCode) {
    const cityName = cityCode.split('_')[0];
    const genre = genreCode;

    return `${genre} Producer & Music Label in ${cityName} | DJBILBOX`;
  }

  /**
   * Generate intro section with cultural context
   */
  generateIntroSection(cityData, genreData) {
    return `
Based in ${cityData.culturalContext || 'a vibrant music hub'}, I'm a professional ${genreData.characteristics} producer
with a unique approach to beat creation and music production. My work combines the rich cultural heritage of
${cityData.culturalAssets.slice(0, 2).join(' and ')} with modern production techniques.

Whether you're looking for:
- Custom beats tailored to your style
- Mixing & mastering services
- VST plugin development for your production workflow
- Label distribution and management

I provide end-to-end music production solutions for independent artists worldwide.
    `.trim();
  }

  /**
   * Generate cultural/local context section
   */
  generateCulturalContext(cityData, genreData) {
    return {
      introduction: `The ${genreData.code} scene in ${Object.keys(cityData).includes('culturalContext') ? cityData.culturalContext : 'this region'} has a unique identity.`,
      assets: cityData.culturalAssets,
      studioHeritage: cityData.studioExamples || [],
      genreCharacteristics: genreData.characteristics,
      caseStudy: this.generateCaseStudy(cityData, genreData)
    };
  }

  /**
   * Generate realistic use cases
   */
  generateUseCases(cityData, genreData) {
    const audienceType = genreData.audience;

    return [
      {
        title: `For ${audienceType} in ${cityData.name || 'your city'}`,
        description: `As a local producer, I understand the specific needs of ${audienceType.toLowerCase()}.
        The ${genreData.code} scene requires specific production aesthetics and mixing approaches.`,
        benefit: "Custom beats that fit your scene's sound signature"
      },
      {
        title: `VST & Technical Integration`,
        description: `Beyond beat production, I develop custom VST plugins tailored to ${genreData.code} production workflows.
        This ensures your creative tools match your artistic vision.`,
        benefit: "Integrated hardware/software setup optimized for your genre"
      },
      {
        title: `Label Services & Distribution`,
        description: `Handle all your distribution, mastering, and rights management through our label services.
        From ${cityData.culturalAssets[0] || 'local studios'} to global streaming platforms.`,
        benefit: "Professional label support without losing creative control"
      }
    ];
  }

  /**
   * Generate CTA (Call-to-Action) - varies by city/genre appeal
   */
  generateCTA(cityCode, genreCode) {
    return {
      primary: `Get Your ${genreCode} Beat Customized`,
      secondary: `Schedule a Free Production Consultation`,
      formAction: `/contact/?city=${cityCode}&genre=${genreCode}`,
      urgency: `Limited availability for Q4 2026 projects in your region`
    };
  }

  /**
   * Generate FAQ section specific to city/genre combo
   */
  generateFAQ(cityData, genreData) {
    return [
      {
        question: `What makes ${genreData.code} production different in ${cityData.name || 'this market'}?`,
        answer: `${genreData.characteristics}. Additionally, local artists often require specific mixing approaches
        aligned with ${cityData.culturalAssets[0] || 'regional studio standards'}.`
      },
      {
        question: `Do you offer remote sessions for ${genreData.code} production?`,
        answer: `Yes. While based in ${cityData.name}, I work with artists globally via file exchange and video sessions.
        However, local artists get priority booking slots.`
      },
      {
        question: `Can you develop custom VST plugins for my ${genreData.code} workflow?`,
        answer: `Absolutely. Many producers in the ${genreData.code} scene benefit from genre-specific tools.
        I offer full consultation on DSP optimization and GUI design.`
      },
      {
        question: `What distribution options do your label services provide?`,
        answer: `Full distribution to Spotify, Apple Music, Deezer, Bandcamp, and physical formats (vinyl, CD).
        Additionally, I handle royalty splits, editorial pitching, and analytics for your releases.`
      }
    ];
  }

  /**
   * Generate internal links - connect to related hubs/spokes
   */
  generateInternalLinks(hubPath, cityCode, genreCode) {
    const cityName = cityCode.split('_')[0];
    const genre = genreCode;

    return {
      relatedGenres: [
        { text: `Other genres in ${cityName}`, href: `/beatmaker-producer/${cityName.toLowerCase()}/` }
      ],
      relatedCities: [
        { text: `Hip-Hop production in London`, href: `/beatmaker-producer/london/grime-garage/` },
        { text: `Trap beats in Atlanta`, href: `/beatmaker-producer/atlanta/trap/` }
      ],
      relatedProducts: [
        { text: `VST plugins for ${genre} production`, href: `/vst-plugins-audio/beatmaker-essentials/` },
        { text: `Mixing & mastering plugins`, href: `/vst-plugins-audio/mixing-mastering/` }
      ],
      relatedServices: [
        { text: `Label distribution & mastering`, href: `/label-musical/distribution/` },
        { text: `Artist website development`, href: `/developpeur-web/artiste-portfolio/` }
      ]
    };
  }

  /**
   * Generate JSON-LD LocalBusiness schema
   */
  generateLocalBusinessSchema(cityCode) {
    const cityData = this.structure.site.contextualVariables.cities[cityCode.split('_')[0]];
    const [city, country] = cityCode.split('_');

    return {
      "@context": "https://schema.org",
      "@type": "LocalBusiness",
      "name": "DJBILBOX BEATS",
      "description": `Professional music production, beat creation, VST development in ${city}`,
      "foundingDate": "2010",
      "url": `https://djbilboxbeats.com/beatmaker-producer/${city.toLowerCase()}/`,
      "address": {
        "@type": "PostalAddress",
        "addressLocality": city,
        "addressCountry": country
      },
      "serviceArea": {
        "@type": "City",
        "name": city
      },
      "areaServed": ["FR", "UK", "US"],
      "contactPoint": {
        "@type": "ContactPoint",
        "contactType": "Customer Service",
        "email": "djbilbox@gmail.com"
      }
    };
  }

  /**
   * Generate JSON-LD MusicGroup schema
   */
  generateMusicGroupSchema(cityCode, genreCode) {
    const city = cityCode.split('_')[0];

    return {
      "@context": "https://schema.org",
      "@type": "MusicGroup",
      "name": `DJBILBOX - ${genreCode} Producer`,
      "url": `https://djbilboxbeats.com/beatmaker-producer/${city.toLowerCase()}/${genreCode.toLowerCase()}/`,
      "genre": genreCode,
      "foundingLocation": { "@type": "City", "name": city },
      "knowsAbout": [genreCode, "Beat Production", "Audio Engineering", "VST Development"],
      "sameAs": [
        "https://spotify.com/artist/...",
        "https://beatstars.com/djbilbox",
        "https://soundcloud.com/djbilbox"
      ]
    };
  }

  /**
   * Generate breadcrumb schema
   */
  generateBreadcrumb(hubPath, cityCode, genreCode) {
    const city = cityCode.split('_')[0];
    const genre = genreCode;

    return {
      "@context": "https://schema.org",
      "@type": "BreadcrumbList",
      "itemListElement": [
        {
          "@type": "ListItem",
          "position": 1,
          "name": "Home",
          "item": "https://djbilboxbeats.com"
        },
        {
          "@type": "ListItem",
          "position": 2,
          "name": "Beatmaker Producer",
          "item": `https://djbilboxbeats.com/beatmaker-producer/`
        },
        {
          "@type": "ListItem",
          "position": 3,
          "name": city,
          "item": `https://djbilboxbeats.com/beatmaker-producer/${city.toLowerCase()}/`
        },
        {
          "@type": "ListItem",
          "position": 4,
          "name": genre,
          "item": `https://djbilboxbeats.com/beatmaker-producer/${city.toLowerCase()}/${genre.toLowerCase()}/`
        }
      ]
    };
  }

  /**
   * Generate keywords
   */
  generateKeywords(cityData, genreData) {
    const city = cityData.name || Object.keys(cityData)[0];
    const genre = genreData.code;

    return [
      `${genre} producer ${city}`,
      `${genre} beatmaker`,
      `beats in ${city}`,
      `music production ${city}`,
      `mixing mastering ${city}`,
      `custom VST plugins`,
      `professional beatmaker`,
      `label distribution`
    ];
  }

  /**
   * Generate related search terms
   */
  generateRelatedTerms(cityData, genreData) {
    const city = Object.keys(cityData)[0];
    const genre = genreData.code;

    return [
      `${genre} ghost producer`,
      `${city} music studios`,
      `beat licensing ${genre}`,
      `sample packs ${genre}`,
      `VST plugins ${genre}`
    ];
  }

  /**
   * Generate case study/success story
   */
  generateCaseStudy(cityData, genreData) {
    const city = Object.keys(cityData)[0];
    return {
      title: `How I Helped a ${genreData.code} Artist Reach 100K Streams`,
      summary: `Artist from ${city} was struggling with production quality.
      Combined custom beat production with VST optimization and label distribution strategy.
      Result: 100K streams in 3 months.`
    };
  }

  /**
   * Simple hash function for deterministic random selection
   */
  hashCode(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash;
    }
    return hash;
  }

  /**
   * Generate slug
   */
  generateSlug(cityCode, genreCode) {
    const city = cityCode.split('_')[0].toLowerCase();
    const genre = genreCode.toLowerCase().replace(/\s+/g, '-');
    return `${city}-${genre}-producer`;
  }
}

// Export for use in Node.js or browser
if (typeof module !== 'undefined' && module.exports) {
  module.exports = ContentInjectionEngine;
}

/**
 * USAGE EXAMPLE
 *
 * const engine = new ContentInjectionEngine(siteStructure);
 * const parisAfrotrapContext = engine.generatePageContext(
 *   '/beatmaker-producer/',
 *   'Paris_FR',
 *   'Afrotrap'
 * );
 *
 * // Output contains:
 * // - Unique title, description, H1
 * // - Paris-specific cultural context + Afrotrap-specific production notes
 * // - Realistic use cases combining both
 * // - Contextual CTA
 * // - Specific internal links
 * // - Localized schema data
 */
